use crate::provenance::{CalcResult,VerificationStatus}; use std::collections::BTreeMap;
pub fn u_factor(center:f64,frame:f64,frame_fraction:f64)->CalcResult { let v=center*(1.0-frame_fraction)+frame*frame_fraction; let mut i=BTreeMap::new();i.insert("center".into(),center);i.insert("frame".into(),frame);i.insert("frame_fraction".into(),frame_fraction);CalcResult::new("U_factor",v,"W/m2K","Ucenter*(1-f_frame)+Uframe*f_frame",i,VerificationStatus::Calculated) }
pub fn cell_temperature(outdoor:f64,g:f64,pce:f64,u:f64)->CalcResult { let h=18.0;let alpha=0.08;let v=outdoor+g*(1.0-pce-alpha)/(1.0/(1.0/u)+1.0/h);let mut i=BTreeMap::new();i.insert("outdoor".into(),outdoor);i.insert("irradiance".into(),g);i.insert("pce".into(),pce);i.insert("u".into(),u);CalcResult::new("T_cell",v,"degC","T_out+G*(1-PCE-alpha)/(1/U+1/h)",i,VerificationStatus::Modeled)}
